package codechicken.lib.raytracer;

import codechicken.lib.vec.Vector3;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.Vec3;

/**
 * Represents a RayTraceResult generated by a {@link IndexedVoxelShape} or {@link MultiIndexedVoxelShape}.
 * <p>
 * Provides easy access to the distance, as well as the {@link IndexedVoxelShape} which the ray hit.
 * <p>
 * Created by covers1624 on 8/9/2016.
 */
public class VoxelShapeBlockHitResult extends SubHitBlockHitResult {

    public IndexedVoxelShape shape;

    public VoxelShapeBlockHitResult(BlockHitResult other, IndexedVoxelShape shape, double dist) {
        super(other.getType()==Type.MISS, other.getLocation(), other.getDirection(), other.getBlockPos(), other.isInside(), other.isWorldBorderHit(), shape.getData(), dist);
        this.shape = shape;
    }

    public VoxelShapeBlockHitResult(Vector3 hit, Direction side, BlockPos pos, boolean isInside, IndexedVoxelShape shape, double dist) {
        super(hit, side, pos, isInside, shape.getData(), dist);
        this.shape = shape;
    }

    public VoxelShapeBlockHitResult(Vector3 hit, Direction side, boolean isInside, IndexedVoxelShape shape, double dist) {
        super(hit, side, BlockPos.ZERO, isInside, shape.getData(), dist);
        this.shape = shape;
    }

    protected VoxelShapeBlockHitResult(boolean isMissIn, Vec3 hit, Direction side, BlockPos pos, boolean isInside, IndexedVoxelShape shape, double dist) {
        this(isMissIn,hit,side,pos,isInside,false,shape,dist);
    }

    protected VoxelShapeBlockHitResult(boolean isMissIn, Vec3 hit, Direction side, BlockPos pos, boolean isInside, boolean worldBorder, IndexedVoxelShape shape, double dist) {
        super(isMissIn,hit,side,pos,isInside,worldBorder,shape.getData(),dist);
        this.shape = shape;
    }

    @Override
    public SubHitBlockHitResult withDirection(Direction newFace) {
        return new VoxelShapeBlockHitResult(getType() == Type.MISS, getLocation(), newFace, getBlockPos(), isInside(), isWorldBorderHit(), shape, dist);
    }

    @Override public VoxelShapeBlockHitResult withPosition(BlockPos pos){return new VoxelShapeBlockHitResult(getType()==Type.MISS,getLocation(),getDirection(),pos,isInside(),isWorldBorderHit(),shape,dist);}
    @Override public VoxelShapeBlockHitResult hitBorder(){return new VoxelShapeBlockHitResult(getType()==Type.MISS,getLocation(),getDirection(),getBlockPos(),isInside(),true,shape,dist);}

    public SubHitBlockHitResult getAsDistanceResult() {
        return new SubHitBlockHitResult(getType() == Type.MISS, getLocation(), getDirection(), getBlockPos(), isInside(), isWorldBorderHit(), hitInfo, dist);
    }

    @Override
    public String toString() {
        return super.toString().replace("}", "") + ", cuboid=" + shape.toString() + "}";
    }
}
